ee:message.ee:set-payload:
%dw 2.0
output application/xml writeDeclaration=false
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/ 
ns por http://schemas.datacontract.org/2004/07/PortalFibra.Modelo.ModeloOrden

var inputValue =if (isEmpty(payload.updateOrderCharacteristics.characteristics))
{
	soapenv#Envelope: {
		soapenv#Header: null,
		soapenv#Body: {
			tem#ActualizarCaracteristicaOrden: {
				tem#Numero_Orden: vars.order_id,
				tem#caracteristicas: {

                },
				tem#usuario: payload.updateOrderCharacteristics.user
			}
		}
	}
}
else
{
	soapenv#Envelope: {
		soapenv#Header: null,
		soapenv#Body: {
			tem#ActualizarCaracteristicaOrden: {
				tem#Numero_Orden: vars.order_id,
				tem#caracteristicas: {
                    por#Caracteristica_Orden: payload.updateOrderCharacteristics.characteristics map (obj, ind) -> {
											por#"_x003C_Caracteristica_x003E_k__BackingField": obj.orderCharacteristic.characteristic,
						por#"_x003C_Valor_x003E_k__BackingField": obj.orderCharacteristic.value
					}
                },
				tem#usuario: payload.updateOrderCharacteristics.user
			}
		}
	}
}
---
inputValue

%dw 2.0
output application/json
---
{
	"updateOrderCharacteristicsOutput": {
    "wsResponseHeader": {
      "system": {
        "correlationId": vars.headersVar.'X-CORRELATION-ID',
        "name": vars.headersVar.'name',
        "processingServer": vars.headersVar.'source'
      },
      "service": {
        "responseDate": vars.responseDate,
        "status": "PASS"
      }
    },
    "bodyResponse": {
      "updateOrderCharacteristicsResponse": {
          "updateOrderCharacteristicsResult": payload.Envelope.Body.ActualizarCaracteristicaOrdenResponse.ActualizarCaracteristicaOrdenResult as Boolean
      }
    }
  }
}
